package zw.co.hyperfeeds.commerce;
import org.slf4j.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import java.time.*;import java.util.*;
@Component class PaymentReconciliationJob{private static final Logger log=LoggerFactory.getLogger(PaymentReconciliationJob.class);private final JdbcClient jdbc;private final PaymentGateway gateway;private final PaymentStateService states;private final Duration timeout;PaymentReconciliationJob(JdbcClient j,PaymentGateway g,PaymentStateService s,@Value("${hyperfeeds.paynow.payment-timeout}")Duration t){jdbc=j;gateway=g;states=s;timeout=t;}@Scheduled(fixedDelayString="${hyperfeeds.paynow.poll-delay}",initialDelayString="10s")void poll(){for(var p:jdbc.sql("select id,poll_url,created_at from payments where status='SENT_TO_SUBSCRIBER' and poll_url is not null order by created_at limit 100").query().listOfRows()){UUID id=(UUID)p.get("id");try{if(((java.time.OffsetDateTime)p.get("created_at")).toInstant().plus(timeout).isBefore(Instant.now())){states.complete(id,false,"TIMEOUT",null,"TIMED_OUT");continue;}var status=gateway.poll((String)p.get("poll_url"));states.complete(id,status.paid(),status.status(),status.paynowReference(),terminalFailure(status.status()));}catch(Exception e){log.warn("Could not reconcile payment {}: {}",id,e.getMessage());}}}private String terminalFailure(String s){return Set.of("CANCELLED","FAILED","ERROR").contains(s.toUpperCase())?"FAILED":null;}}
